      "copy": {
        "pl": {
          "id": "zero-based-budget",
          "question": "Co oznacza „zero” w budżecie od zera?",
          "answers": [
            {
              "id": "A",
              "text": "Trzeba wydać wszystko i opróżnić konto"
            },
            {
              "id": "B",
              "text": "Każda dostępna złotówka ma cel w planie, także rezerwa"
            },
            {
              "id": "C",
              "text": "Oszczędności muszą wynosić zero"
            },
            {
              "id": "D",
              "text": "Wolno używać wyłącznie gotówki"
            }
          ],
          "correctAnswer": "B",
          "reward": 25,
          "successMessage": "To metoda planowania, nie nakaz wydania wszystkiego ani wyzerowania konta. Hipotetycznie: 1000 zł = 800 zł podstawowych potrzeb + 100 zł wymaganych minimalnych spłat + 100 zł dobrowolnej rezerwy; nieprzypisane: 0 zł. Spłaty policzono raz. Przy zmiennym dochodzie aktualizuj plan; bez nadwyżki nie ma obowiązku odkładania. Plan nie gwarantuje braku nieprzewidzianych wydatków.",
          "retryMessage": "To metoda planowania, nie nakaz wydania wszystkiego ani wyzerowania konta. Hipotetycznie: 1000 zł = 800 zł podstawowych potrzeb + 100 zł wymaganych minimalnych spłat + 100 zł dobrowolnej rezerwy; nieprzypisane: 0 zł. Spłaty policzono raz. Przy zmiennym dochodzie aktualizuj plan; bez nadwyżki nie ma obowiązku odkładania. Plan nie gwarantuje braku nieprzewidzianych wydatków.",
          "category": "Budżet domowy"
        },
        "en": {
          "id": "zero-based-budget",
          "question": "What does “zero” mean in zero-based budgeting?",
          "answers": [
            {
              "id": "A",
              "text": "You must spend everything and empty the account"
            },
            {
              "id": "B",
              "text": "Every available unit has a purpose in the plan, including reserves"
            },
            {
              "id": "C",
              "text": "Savings must equal zero"
            },
            {
              "id": "D",
              "text": "Only cash may be used"
            }
          ],
          "correctAnswer": "B",
          "reward": 25,
          "successMessage": "This is a planning method, not a requirement to spend everything or empty an account. Hypothetically: PLN 1000 = 800 for essential needs + 100 for required minimum repayments + 100 for a voluntary reserve; unallocated: PLN 0. Repayments are counted once. Update the plan when income varies; no surplus means no duty to save. The plan does not guarantee freedom from unexpected expenses.",
          "retryMessage": "This is a planning method, not a requirement to spend everything or empty an account. Hypothetically: PLN 1000 = 800 for essential needs + 100 for required minimum repayments + 100 for a voluntary reserve; unallocated: PLN 0. Repayments are counted once. Update the plan when income varies; no surplus means no duty to save. The plan does not guarantee freedom from unexpected expenses.",
          "category": "Budgeting"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Zero dotyczy nieprzypisanej kwoty w planie; przydział do rezerwy nie wymaga wydania ani wypłaty pieniędzy.",
          "en": "Zero refers to unallocated money in the plan; assigning reserves does not require spending or withdrawing it."
        },
        "C": {
          "pl": "Rezerwa lub oszczędności mogą mieć przydział w planie i dodatnie saldo.",
          "en": "Reserves or savings can have a planned allocation and a positive balance."
        },
        "D": {
          "pl": "To sposób planowania przydziałów, a nie ograniczenie do gotówki.",
          "en": "This is a way to plan allocations, not a cash-only restriction."
        }
      },
      "number_model": {
        "kind": "hypothetical-PLN-allocation",
        "assumptions": [
          "Same illustrative period; PLN1000 available, not a national income estimate.",
          "PLN800 essential needs excludes the separately counted PLN100 required minimum repayments.",
          "PLN100 voluntary reserve is an allocation, not required consumption; no surplus never creates a savings obligation."
        ],
        "inputs": {
          "availablePLN": 1000,
          "essentialNeedsPLN": 800,
          "requiredMinimumRepaymentsPLN": 100,
          "voluntaryReservePLN": 100
        },
        "expression": "1000-(800+100+100)",
        "result": {
          "unallocatedPLN": 0
